use crate::content::{file_uris, Content, MAX_IMAGE};
use objc2::{rc::autoreleasepool, runtime::ProtocolObject};
use objc2_app_kit::{NSPasteboard, NSPasteboardItem, NSPasteboardWriting};
use objc2_foundation::{NSArray, NSData, NSString};

pub fn read(board: &NSPasteboard) -> Result<Option<Content>, String> {
    autoreleasepool(|_| {
        let count = board.changeCount();
        let excluded = [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType",
            "com.agilebits.onepassword",
        ];
        if board.types().is_some_and(|types| {
            types
                .iter()
                .any(|t| excluded.contains(&t.to_string().as_str()))
        }) {
            return Ok(None);
        }
        let file_type = NSString::from_str("public.file-url");
        let files: Vec<String> = board
            .pasteboardItems()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| item.stringForType(&file_type))
                    .map(|s| s.to_string())
                    .collect()
            })
            .unwrap_or_default();
        let content = if !files.is_empty() {
            file_uris(files.join("\n").as_bytes())
        } else {
            let mut image = None;
            for (native, mime) in [("public.png", "image/png"), ("public.tiff", "image/tiff")] {
                if let Some(data) = board.dataForType(&NSString::from_str(native)) {
                    if !data.is_empty() && data.len() <= MAX_IMAGE {
                        image = Some(Content::Image {
                            mime,
                            bytes: data.to_vec().into(),
                        });
                    }
                    break;
                }
            }
            image.or_else(|| {
                unsafe { board.stringForType(objc2_app_kit::NSPasteboardTypeString) }
                    .map(|s| Content::from(s.to_string()))
            })
        };
        Ok(content.filter(|c| count == board.changeCount() && c.valid()))
    })
}

pub fn write(board: &NSPasteboard, content: &Content) -> Result<(), String> {
    autoreleasepool(|_| {
        board.clearContents();
        let success = match content {
            Content::Text(text) => unsafe {
                board.setString_forType(
                    &NSString::from_str(text),
                    objc2_app_kit::NSPasteboardTypeString,
                )
            },
            Content::Image { mime, bytes } => board.setData_forType(
                Some(&NSData::with_bytes(bytes)),
                &NSString::from_str(if *mime == "image/png" {
                    "public.png"
                } else {
                    "public.tiff"
                }),
            ),
            Content::Files(uris) => {
                let items: Vec<objc2::rc::Retained<ProtocolObject<dyn NSPasteboardWriting>>> = uris
                    .iter()
                    .map(|uri| {
                        let item = NSPasteboardItem::new();
                        item.setString_forType(
                            &NSString::from_str(uri),
                            &NSString::from_str("public.file-url"),
                        );
                        ProtocolObject::from_retained(item)
                    })
                    .collect();
                board.writeObjects(&NSArray::from_retained_slice(&items))
            }
        };
        if success {
            Ok(())
        } else {
            Err("Couldn't copy this clip. Please try again.".into())
        }
    })
}
